    "pf-apm-alerts-title": "Alertes actives",
    "pf-apm-no-alerts": "Aucune alerte active — toutes les métriques sont dans les seuils.",
    "pf-apm-chart-response-time": "Temps de réponse dans le temps",
    "pf-apm-chart-response-time-desc": "Durée par requête (ms) pour les {n} dernières requêtes, de la plus ancienne à la plus récente.",
    "pf-apm-chart-volume": "Volume de requêtes par route",
