    "pf-apm-col-avg": "Moy. (ms)",
    "pf-apm-col-max": "Max (ms)",
    "pf-apm-col-errors": "Erreurs",
    "pf-apm-col-slow": "Lentes",
    "pf-apm-status-2xx": "Succès 2xx",
    "pf-apm-status-3xx": "Redirection 3xx",
    "pf-apm-status-4xx": "Erreur client 4xx",
    "pf-apm-status-5xx": "Erreur serveur 5xx",
