    "pf-ma-card-posts-by-status": "Annonces par statut",
    "pf-ma-card-posts-by-type": "Annonces par type",
    "pf-ma-card-recent-activity": "Activité récente",
    "pf-ma-card-recent-activity-desc": "Derniers événements d'audit de la place de marché, toutes plateformes confondues.",
