    "ref-ag-s1-title": "1. Parties et objet",
    "ref-ag-s1-body": "Le présent contrat établit la coopération entre la société qui exploite cette plateforme et vous-même en tant que partenaire apporteur : vous présentez des sociétés clientes et des opportunités d'affaires, et vous percevez une commission sur les affaires concrétisées avec les sociétés que vous recommandez.",
    "ref-ag-s2-title": "2. Votre rôle de partenaire apporteur",
    "ref-ag-s2-l1": "Vous présentez des sociétés clientes et des opportunités d'affaires que vous représentez ou avec lesquelles vous entretenez une relation réelle.",
