    "ref-ag-s4-body": "La commission devient exigible lorsque l'affaire recommandée est confirmée comme conclue, que tous les documents requis sont fournis et que la commission est approuvée. Les versements sont effectués sur le compte bancaire que vous désignez dans Coordonnées de paiement.",
    "ref-ag-s5-title": "5. Confidentialité",
    "ref-ag-s5-body": "Les conditions du présent contrat, l'identité des sociétés recommandées et toutes les informations commerciales échangées sont confidentielles et ne peuvent être divulguées à des tiers.",
    "ref-ag-s6-title": "6. Durée et modifications",
    "ref-ag-s6-body": "Le contrat s'applique de son acceptation jusqu'à sa résiliation par écrit. En cas de modification des conditions, une nouvelle version est émise et votre réacceptation est requise ; votre acceptation précédente reste archivée.",
