    "marketplace-kyc-verified": "KYC vérifié",
    "marketplace-kyc-not-verified": "KYC non vérifié",
    "marketplace-dd-banner-title": "Commercez en toute sécurité — effectuez votre propre due diligence",
    "marketplace-dd-banner-short": "VELOS est un point de rencontre neutre qui met en relation acheteurs et vendeurs. Nous ne sommes partie à aucune transaction, ne manipulons ni marchandises ni fonds, et n'acceptons aucune responsabilité pour les affaires conclues entre membres.",
    "marketplace-dd-banner-full": "Avant de vous engager : vérifiez l'immatriculation et la réputation de la contrepartie, confirmez les licences et certificats, exigez un paiement sécurisé (séquestre ou lettre de crédit) et assurez-vous que l'opération est conforme aux lois qui vous concernent.",
    "marketplace-dd-open-safety": "Guide de sécurité et de conformité",
    "marketplace-dd-show-more": "Afficher plus",
    "marketplace-dd-show-less": "Afficher moins",
    "marketplace-dd-panel-title": "Sécurité et conformité",
    "marketplace-dd-panel-subtitle": "Conseils pratiques de due diligence que chaque membre de la place de marché devrait suivre avant d'envoyer de l'argent ou des marchandises.",
    "marketplace-dd-panel-liability": "VELOS fournit uniquement des mises en relation et des outils. Nous ne sommes partie à aucun contrat, ne détenons ni ne transportons de marchandises ou de fonds, ne certifions pas la légalité d'une annonce et n'acceptons aucune responsabilité pour toute perte résultant d'une transaction entre membres. Effectuez toujours votre propre due diligence et vos propres contrôles de conformité.",
    "marketplace-dd-s1-title": "1. Vérifiez la contrepartie",
    "marketplace-dd-s1-body": "Vérifiez le numéro d'immatriculation de la société, le statut TVA/EORI et l'adresse physique auprès des registres officiels. Sur VELOS, privilégiez les partenaires portant le badge KYC vérifié — leur identité et leurs documents ont été examinés — et consultez les évaluations des affaires passées. Un appel et une visite vidéo des locaux sont une assurance à peu de frais.",
    "marketplace-dd-s2-title": "2. Sécurisez le paiement",
    "marketplace-dd-s2-body": "Recourez au séquestre ou à une lettre de crédit irrévocable avec les nouvelles contreparties ; VELOS prend en charge les deux. Évitez les paiements d'acompte en espèces vers des comptes inconnus et ne payez jamais sur un compte bancaire personnel. Adossez l'échéancier de paiement aux jalons de livraison afin qu'aucun montant important ne soit en risque à un instant donné.",
    "marketplace-dd-s3-title": "3. Vérifiez les marchandises",
    "marketplace-dd-s3-body": "Demandez les certificats d'analyse, les spécifications de qualité et, le cas échéant, les documents d'origine avant de contracter. Recourez à une inspection avant expédition (SGS, Bureau Veritas ou un agent de confiance) et conservez le droit de refuser des marchandises non conformes aux spécifications convenues.",
    "marketplace-dd-s4-title": "4. Mettez tout par écrit",
    "marketplace-dd-s4-body": "Signez un véritable contrat de vente/achat : spécification du produit, Incoterms 2020, échéancier de livraison, conditions de paiement, droits d'inspection, règlement des litiges et droit applicable. Les modèles de documents VELOS et l'historique de négociation peuvent y contribuer, mais ils ne remplacent pas votre propre analyse juridique.",
    "marketplace-dd-s5-title": "5. Respectez les règles de conformité",
    "marketplace-dd-s5-body": "Les listes de sanctions (UN, EU, OFAC), les contrôles à l'exportation, les biens à double usage, les obligations AML/KYC et les règles douanières s'appliquent à vous personnellement comme à votre société. Il vous incombe — non à VELOS — de vous assurer qu'une opération envisagée est légale pour les deux parties.",
    "marketplace-dd-s6-title": "6. Signalez les activités suspectes",
    "marketplace-dd-s6-body": "Si une annonce semble frauduleuse, trompeuse ou interdite, signalez-la avec le bouton Signaler sur la publication. Notre équipe examine chaque signalement. Si une affaire a déjà mal tourné, contactez immédiatement votre banque et faites intervenir les forces de l'ordre de votre juridiction — VELOS peut appuyer les enquêtes avec les données qu'il détient légalement.",
    "marketplace-locked-tier-title": "Les communications sont verrouillées sur votre palier",
    "marketplace-locked-tier-body": "Tout le monde peut parcourir cette place de marché, mais la publication, les réponses, les négociations et les enchères exigent le palier Standard ou supérieur. Améliorez le palier de votre portail pour débloquer les communications.",
    "marketplace-locked-tier-body-respond": "Répondre à cette publication exige le palier Standard ou supérieur. Améliorez le palier de votre portail pour envoyer des offres.",
    "marketplace-locked-tier-body-negotiate": "Envoyer des messages ou des offres exige le palier Standard ou supérieur. Améliorez le palier de votre portail pour poursuivre la négociation.",
    "marketplace-locked-tier-body-bid": "Placer des enchères exige le palier Standard ou supérieur. Améliorez le palier de votre portail pour participer aux enchères.",
    "marketplace-locked-tier-body-qa": "Poser ou répondre à des questions exige le palier Standard ou supérieur. Améliorez le palier de votre portail pour rejoindre la discussion.",
    "marketplace-locked-kyc-title": "Vérification KYC requise",
    "marketplace-locked-kyc-body": "Pour communiquer sur la place de marché, votre examen KYC doit être entièrement approuvé — identité, société et documents bancaires vérifiés. Finalisez votre examen KYC ou attendez son aboutissement pour débloquer la publication, les réponses et les enchères.",
    "marketplace-locked-kyc-body-respond": "Votre examen KYC doit être entièrement approuvé avant de pouvoir répondre aux publications. Veuillez finaliser votre examen KYC ou attendre son aboutissement.",
    "marketplace-locked-kyc-body-negotiate": "Votre examen KYC doit être entièrement approuvé avant de pouvoir envoyer des messages ou des offres. Veuillez finaliser votre examen KYC ou attendre son aboutissement.",
    "marketplace-locked-kyc-body-bid": "Votre examen KYC doit être entièrement approuvé avant de pouvoir placer des enchères. Veuillez finaliser votre examen KYC ou attendre son aboutissement.",
    "marketplace-locked-kyc-body-qa": "Votre examen KYC doit être entièrement approuvé avant de pouvoir poser ou répondre à des questions. Veuillez finaliser votre examen KYC ou attendre son aboutissement.",
    "marketplace-locked-upgrade-cta": "Demander une amélioration de palier",
    "marketplace-locked-kyc-cta": "Accéder à la vérification KYC",
    "marketplace-dd-form-note": "VELOS met en relation des opérateurs du commerce mais n'est pas partie à votre affaire — vérifiez la contrepartie, convenez d'un paiement sécurisé (séquestre/LC) et formalisez les conditions par écrit avant de vous engager.",
    "marketplace-watchlist": "Liste de suivi",
